25	pub fn run(args: &HookHandlerArgs) -> Result<()> {
26	    // Find the git dir by discovering the repo
27	    let storage = GitStorage::discover().context("Not inside a Git repository")?;
28	    let git_dir = storage.repo().path().to_path_buf();
29	
30	    match args.hook_name.as_str() {
31	        "prepare-commit-msg" => {
32	            // Auto-capture: if enabled and no active session, import current Claude Code session
33	            maybe_auto_capture(&storage, &git_dir);
34	
35	            let msg_file = args
36	                .args
37	                .first()
38	                .map(PathBuf::from)
39	                .context("prepare-commit-msg: missing message file argument")?;
40	            hooks::handle_prepare_commit_msg(&msg_file, &git_dir)?;
41	        }
42	        "post-commit" => {
43	            hooks::handle_post_commit(&git_dir)?;
44	
45	            // Auto-capture cleanup: if session was auto-created, clean it up
46	            maybe_auto_capture_cleanup(&storage, &git_dir);
47	        }
48	        "pre-push" => {
49	            maybe_auto_push(&storage);
50	        }
51	        "session-end" => {
52	            handle_session_end(&storage);
53	        }
54	        other => {
55	            tracing::debug!("Unknown hook: {other}, ignoring");
56	        }
57	    }
58	
59	    Ok(())
60	}
