62	/// Handle Claude Code's `SessionEnd` hook.
63	///
64	/// Reads JSON from stdin (provided by Claude Code), extracts the `transcript_path`,
65	/// and imports the session as an engram. All errors are logged at debug level and
66	/// silently ignored so we never interfere with the user's workflow.
67	fn handle_session_end(storage: &GitStorage) {
68	    let mut input = String::new();
69	    if std::io::stdin().read_to_string(&mut input).is_err() {
70	        tracing::debug!("session-end: failed to read stdin");
71	        return;
72	    }
73	
74	    let json: serde_json::Value = match serde_json::from_str(&input) {
75	        Ok(v) => v,
76	        Err(e) => {
77	            tracing::debug!("session-end: failed to parse JSON: {e}");
78	            return;
79	        }
80	    };
81	
82	    let transcript_path = match json.get("transcript_path").and_then(|v| v.as_str()) {
83	        Some(p) => std::path::PathBuf::from(p),
84	        None => {
85	            tracing::debug!("session-end: no transcript_path in input");
86	            return;
87	        }
88	    };
89	
90	    if !transcript_path.exists() {
91	        tracing::debug!(
92	            "session-end: transcript file does not exist: {}",
93	            transcript_path.display()
94	        );
95	        return;
96	    }
97	
98	    let mut data = match ClaudeCodeImporter::import_session(&transcript_path) {
99	        Ok(d) => d,
100	        Err(e) => {
101	            tracing::debug!("session-end: failed to import session: {e}");
102	            return;
103	        }
104	    };
105	
106	    // Best-effort LLM summarization
107	    if let Err(e) = summarize_intent(&mut data) {
108	        tracing::debug!("session-end: LLM summarization failed: {e}");
109	    }
110	
111	    // Check for duplicates via source_hash
112	    if let Some(existing_id) = data
113	        .manifest
114	        .source_hash
115	        .as_deref()
116	        .and_then(|h| storage.find_by_source_hash(h))
117	    {
118	        tracing::debug!(
119	            "session-end: already imported as {}",
120	            &existing_id.as_str()[..8]
121	        );
122	        return;
123	    }
124	
125	    let id = data.manifest.id.clone();
126	    match storage.create(&data) {
127	        Ok(_) => {
128	            // Best-effort index update
129	            if let Ok(engine) = SearchEngine::open(storage) {
130	                let _ = engine.index_engram(&data);
131	            }
132	            tracing::debug!("session-end: imported engram {}", &id.as_str()[..8]);
133	
134	            // Best-effort: annotate commits that reference this engram
135	            auto_annotate_commits(storage, &data);
136	        }
137	        Err(e) => {
138	            tracing::debug!("session-end: failed to store engram: {e}");
139	        }
140	    }
141	}
