143	/// Scan recent commits for Engram-Id trailers matching the given engram,
144	/// and attach git notes with rich reasoning metadata.
145	fn auto_annotate_commits(storage: &GitStorage, data: &engram_core::model::EngramData) {
146	    use engram_core::notes::{format_note, ENGRAM_NOTES_REF};
147	
148	    let repo = storage.repo();
149	    let engram_id_str = data.manifest.id.as_str().to_string();
150	
151	    // Walk recent commits looking for Engram-Id trailers
152	    let head = match repo.head().and_then(|h| h.peel_to_commit()) {
153	        Ok(c) => c,
154	        Err(_) => return,
155	    };
156	
157	    let sig = repo
158	        .signature()
159	        .unwrap_or_else(|_| git2::Signature::now("engram", "engram@localhost").unwrap());
160	
161	    let mut revwalk = match repo.revwalk() {
162	        Ok(r) => r,
163	        Err(_) => return,
164	    };
165	    if revwalk.push(head.id()).is_err() {
166	        return;
167	    }
168	
169	    let note = format_note(data);
170	    let mut annotated = 0;
171	
172	    for oid_result in revwalk.take(50) {
173	        let oid = match oid_result {
174	            Ok(o) => o,
175	            Err(_) => break,
176	        };
177	        let commit = match repo.find_commit(oid) {
178	            Ok(c) => c,
179	            Err(_) => continue,
180	        };
181	
182	        if let Some(message) = commit.message() {
183	            for line in message.lines() {
184	                if let Some(trailer_id) = line.strip_prefix("Engram-Id: ") {
185	                    if trailer_id.trim() == engram_id_str {
186	                        // Skip if already annotated
187	                        if repo.find_note(Some(ENGRAM_NOTES_REF), oid).is_ok() {
188	                            continue;
189	                        }
190	                        if repo
191	                            .note(&sig, &sig, Some(ENGRAM_NOTES_REF), oid, &note, false)
192	                            .is_ok()
193	                        {
194	                            annotated += 1;
195	                        }
196	                    }
197	                }
198	            }
199	        }
200	    }
201	
202	    if annotated > 0 {
203	        tracing::debug!("session-end: annotated {annotated} commit(s) with engram notes");
204	    }
205	}
