319	/// After post-commit, if the session was auto-created, update the engram
320	/// with the commit SHA and clean up the session file.
321	fn maybe_auto_capture_cleanup(storage: &GitStorage, git_dir: &std::path::Path) {
322	    let session = match ActiveSession::load(git_dir) {
323	        Some(s) if s.auto_capture => s,
324	        _ => return,
325	    };
326	
327	    // The core post-commit handler already recorded the commit SHA in the session.
328	    // Now read back the session to get the commit, update the engram, and clean up.
329	    let updated = ActiveSession::load(git_dir).unwrap_or(session);
330	
331	    if !updated.commits.is_empty() {
332	        // Re-read the engram, update its git_commits, and re-store it
333	        if let Ok(mut data) = storage.read(updated.engram_id.as_str()) {
334	            for sha in &updated.commits {
335	                if !data.manifest.git_commits.contains(sha) {
336	                    data.manifest.git_commits.push(sha.clone());
337	                }
338	                if !data.lineage.git_commits.contains(sha) {
339	                    data.lineage.git_commits.push(sha.clone());
340	                }
341	            }
342	            // Re-store the updated engram (overwrites the ref)
343	            let _ = storage.create(&data);
344	        }
345	    }
346	
347	    ActiveSession::cleanup(git_dir);
348	    tracing::debug!(
349	        "Auto-capture: finalized engram {} with {} commit(s)",
350	        &updated.engram_id.as_str()[..8],
351	        updated.commits.len()
352	    );
353	}
