355	/// If push_on_push is enabled, automatically push engram refs alongside code.
356	/// Uses the git CLI instead of libgit2 so it inherits the user's credential helpers.
357	/// Sets ENGRAM_PUSHING=1 to prevent recursive hook invocation.
358	fn maybe_auto_push(storage: &GitStorage) {
359	    // Guard against recursive invocation: our `git push` triggers pre-push again
360	    if std::env::var_os("ENGRAM_PUSHING").is_some() {
361	        return;
362	    }
363	
364	    let config = match load_config(storage) {
365	        Some(c) => c,
366	        None => return,
367	    };
368	
369	    if !config.push_on_push {
370	        return;
371	    }
372	
373	    let workdir = match storage.workdir() {
374	        Some(w) => w.to_path_buf(),
375	        None => return,
376	    };
377	
378	    // Force-push engram refs: they may be updated in-place (e.g. when commit SHAs
379	    // are appended), so the push is not necessarily a fast-forward.
380	    match std::process::Command::new("git")
381	        .args([
382	            "push",
383	            "--force",
384	            "origin",
385	            "+refs/engrams/*:refs/engrams/*",
386	        ])
387	        .env("ENGRAM_PUSHING", "1")
388	        .current_dir(&workdir)
389	        .stdout(std::process::Stdio::piped())
390	        .stderr(std::process::Stdio::piped())
391	        .output()
392	    {
393	        Ok(output) if output.status.success() => {
394	            let stderr = String::from_utf8_lossy(&output.stderr);
395	            let pushed = stderr.lines().filter(|l| l.contains("->")).count();
396	            if pushed > 0 {
397	                eprintln!("engram: pushed {pushed} engram ref(s) to origin");
398	            }
399	        }
400	        Ok(output) => {
401	            // Silently log failures — don't pollute the user's git push output
402	            let stderr = String::from_utf8_lossy(&output.stderr);
403	            tracing::debug!("Auto-push: git push failed: {stderr}");
404	        }
405	        Err(e) => {
406	            tracing::debug!("Auto-push: failed to run git: {e}");
407	        }
408	    }
409	}
