43	/// Spawn a background thread for update checking.
44	/// Returns None for commands that should not trigger checks.
45	fn maybe_spawn_update_check(
46	    command: &commands::Commands,
47	) -> Option<mpsc::Receiver<Option<engram_core::update::UpdateInfo>>> {
48	    // Skip for internal/long-running commands
49	    if matches!(
50	        command,
51	        commands::Commands::HookHandler(_)
52	            | commands::Commands::Mcp
53	            | commands::Commands::Browse(_)
54	            | commands::Commands::Dashboard(_)
55	            | commands::Commands::Version
56	    ) {
57	        return None;
58	    }
59	
60	    // Skip if disabled (cheap check before spawning thread)
61	    if engram_core::update::is_update_check_disabled() {
62	        return None;
63	    }
64	
65	    let (tx, rx) = mpsc::channel();
66	    let current = env!("CARGO_PKG_VERSION").to_string();
67	
68	    std::thread::spawn(move || {
69	        let result = engram_core::update::check_for_update(&current, false);
70	        let _ = tx.send(result);
71	    });
72	
73	    Some(rx)
74	}
