82	
83	    let result = match &cli.command {
84	        commands::Commands::Init(args) => commands::init::run(args),
85	        commands::Commands::Config(args) => commands::config::run(args),
86	        commands::Commands::Record(args) => commands::record::run(args),
87	        commands::Commands::Import(args) => commands::import::run(args),
88	        commands::Commands::Log(args) => commands::log::run(args, cli.format),
89	        commands::Commands::Show(args) => commands::show::run(args, cli.format),
90	        commands::Commands::Search(args) => commands::search::run(args, cli.format),
91	        commands::Commands::Trace(args) => commands::trace::run(args, cli.format),
92	        commands::Commands::Diff(args) => commands::diff::run(args, cli.format),
93	        commands::Commands::Graph(args) => commands::graph::run(args, cli.format),
94	        commands::Commands::Review(args) => commands::review::run(args, cli.format),
95	        commands::Commands::Mcp => commands::mcp::run(),
96	        commands::Commands::PrSummary(args) => commands::pr_summary::run(args, cli.format),
97	        commands::Commands::Push(args) => commands::push::run(args),
98	        commands::Commands::Pull(args) => commands::pull::run(args),
99	        commands::Commands::Fetch(args) => commands::fetch::run(args),
100	        commands::Commands::Stats(args) => commands::stats::run(args, cli.format),
101	        commands::Commands::DeadEnds(args) => commands::dead_ends::run(args, cli.format),
102	        commands::Commands::Gc(args) => commands::gc::run(args),
103	        commands::Commands::Blame(args) => commands::blame::run(args, cli.format),
104	        commands::Commands::Reindex => commands::reindex::run(),
105	        commands::Commands::Why(args) => commands::why::run(args, cli.format),
106	        commands::Commands::Annotate(args) => commands::annotate::run(args),
107	        commands::Commands::Audit(args) => commands::audit::run(args, cli.format),
108	        commands::Commands::Browse(args) => commands::browse::run(args),
109	        commands::Commands::Dashboard(args) => commands::dashboard::run(args),
110	        commands::Commands::Version => commands::version::run(),
111	        commands::Commands::HookHandler(args) => commands::hook_handler::run(args),
112	    };
113	
114	    // After command completes, check if update notification is ready
115	    if let Some(rx) = update_rx {
116	        if let Ok(Some(info)) = rx.try_recv() {
117	            if std::io::stderr().is_terminal() {
118	                eprintln!("{}", engram_core::update::format_update_notice(&info));
119	            }
120	        }
121	    }
122	
123	    result
