52	        let mut config = self.repo.config().map_err(CoreError::Git)?;
53	        let engram_config = EngramConfig::default_init();
54	        engram_config.save(&mut config)?;
55	
56	        // Set schema version
57	        config
58	            .set_i32("engram.version", 1)
59	            .map_err(CoreError::Git)?;
60	
61	        // Add engram fetch/push refspecs to remotes
62	        self.configure_remotes_filtered(remote)?;
63	
64	        Ok(())
65	    }
66	
67	    /// Initialize engram in this repo: set config, configure refspecs on all remotes.
68	    pub fn init(&self) -> Result<(), CoreError> {
69	        self.init_with_remote(None)
70	    }
71	
72	    /// Create a new engram and store it as Git objects.
73	    pub fn create(&self, data: &EngramData) -> Result<EngramId, CoreError> {
74	        let commit_oid = create_engram_objects(&self.repo, data)?;
75	        let id = data.manifest.id.clone();
76	        refs::create_engram_ref(&self.repo, &id, commit_oid)?;
77	        // Update engram-head pointer for O(1) HEAD resolution
78	        self.update_head_pointer(&id, &data.manifest.created_at);
79	        Ok(id)
80	    }
81	
82	    /// Resolve "HEAD" to the most recent engram ID, or pass through to prefix resolution.
83	    pub fn resolve(&self, id_or_alias: &str) -> Result<String, CoreError> {
84	        if id_or_alias.eq_ignore_ascii_case("HEAD") {
85	            // Fast path: try engram-head pointer file
86	            if let Some(head_id) = self.read_head_pointer() {
87	                // Validate the ref still exists
88	                if refs::resolve_engram_ref(&self.repo, &head_id).is_ok() {
89	                    return Ok(head_id);
90	                }
91	            }
92	            // Fallback: O(n) scan
93	            let manifests = self.list(&ListOptions::default())?;
94	            if let Some(m) = manifests.first() {
95	                // Repair the head pointer
96	                self.update_head_pointer(&m.id, &m.created_at);
97	                Ok(m.id.as_str().to_string())
98	            } else {
99	                Err(CoreError::NotFound {
100	                    id: "HEAD (no engrams exist)".to_string(),
101	                })
102	            }
103	        } else {
104	            let (id, _oid) = refs::resolve_engram_ref(&self.repo, id_or_alias)?;
105	            Ok(id.as_str().to_string())
106	        }
107	    }
108	
109	    /// Read an engram by its ID (or prefix).
110	    pub fn read(&self, id_or_prefix: &str) -> Result<EngramData, CoreError> {
111	        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
112	        read::read_engram(&self.repo, oid)
113	    }
114	
115	    /// Read only the manifest (fast path for listing).
116	    pub fn read_manifest(&self, id_or_prefix: &str) -> Result<Manifest, CoreError> {
117	        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
118	        read::read_manifest(&self.repo, oid)
119	    }
120	
121	    /// List all engrams, optionally filtered.
122	    pub fn list(&self, opts: &ListOptions) -> Result<Vec<Manifest>, CoreError> {
123	        let all_refs = refs::list_engram_refs(&self.repo)?;
124	        let mut manifests = Vec::with_capacity(all_refs.len());
125	
126	        for (_id, oid) in &all_refs {
127	            match read::read_manifest(&self.repo, *oid) {
128	                Ok(manifest) => {
129	                    // Apply agent filter
130	                    if let Some(agent) = &opts.agent_filter {
131	                        if !manifest.agent.name.contains(agent.as_str()) {
132	                            continue;
133	                        }
134	                    }
135	                    manifests.push(manifest);
136	                }
137	                Err(e) => {
138	                    tracing::warn!("Skipping unreadable engram: {e}");
139	                }
140	            }
141	        }
142	
143	        // Sort by created_at descending (most recent first)
144	        manifests.sort_by(|a, b| b.created_at.cmp(&a.created_at));
145	
146	        // Apply limit
147	        if let Some(limit) = opts.limit {
148	            manifests.truncate(limit);
149	        }
150	
151	        Ok(manifests)
152	    }
