154	    /// Check if an engram with the given source hash already exists.
155	    /// Used for import deduplication.
156	    pub fn find_by_source_hash(&self, hash: &str) -> Option<EngramId> {
157	        let all_refs = refs::list_engram_refs(&self.repo).ok()?;
158	        for (id, oid) in &all_refs {
159	            if let Ok(manifest) = read::read_manifest(&self.repo, *oid) {
160	                if manifest.source_hash.as_deref() == Some(hash) {
161	                    return Some(id.clone());
162	                }
163	            }
164	        }
165	        None
166	    }
