168	    /// Find the engram that produced a given git commit SHA.
169	    /// Searches `manifest.git_commits` across all engrams.
170	    pub fn find_by_commit_sha(&self, sha: &str) -> Option<EngramId> {
171	        let all_refs = refs::list_engram_refs(&self.repo).ok()?;
172	        for (_id, oid) in &all_refs {
173	            if let Ok(manifest) = read::read_manifest(&self.repo, *oid) {
174	                if manifest.git_commits.iter().any(|c| c == sha) {
175	                    return Some(manifest.id);
176	                }
177	            }
178	        }
179	        None
180	    }
