198	    /// Update the engram-head pointer file. Only updates if this engram is newer.
199	    /// Best-effort — failures are silently ignored.
200	    fn update_head_pointer(&self, id: &EngramId, created_at: &chrono::DateTime<chrono::Utc>) {
201	        // repo.path() returns the .git dir (or the repo dir for bare repos)
202	        let head_path = self.repo.path().join(ENGRAM_HEAD_FILE);
203	
204	        // Read existing pointer to check timestamp
205	        if let Ok(existing) = std::fs::read_to_string(&head_path) {
206	            // Format: "<id> <rfc3339-timestamp>"
207	            if let Some(ts_str) = existing.split_whitespace().nth(1) {
208	                if let Ok(existing_ts) = ts_str.parse::<chrono::DateTime<chrono::Utc>>() {
209	                    if existing_ts >= *created_at {
210	                        return; // Existing head is newer or same
211	                    }
212	                }
213	            }
214	        }
215	
216	        let content = format!("{} {}", id.as_str(), created_at.to_rfc3339());
217	        let _ = std::fs::write(&head_path, content);
218	    }
219	
220	    /// Read the engram-head pointer file. Returns the ID if valid.
221	    fn read_head_pointer(&self) -> Option<String> {
222	        let head_path = self.repo.path().join(ENGRAM_HEAD_FILE);
223	        let content = std::fs::read_to_string(&head_path).ok()?;
224	        content.split_whitespace().next().map(String::from)
225	    }
226	
227	    /// Configure fetch/push refspecs for engram refs on remotes.
228	    /// If `filter` is Some, only configure that specific remote.
229	    fn configure_remotes_filtered(&self, filter: Option<&str>) -> Result<(), CoreError> {
230	        let remotes = self.repo.remotes().map_err(CoreError::Git)?;
231	        let mut config = self.repo.config().map_err(CoreError::Git)?;
232	
233	        for remote_name in remotes.iter().flatten() {
234	            if let Some(target) = filter {
235	                if remote_name != target {
236	                    continue;
237	                }
238	            }
239	            let fetch_key = format!("remote.{remote_name}.fetch");
240	            let push_key = format!("remote.{remote_name}.push");
241	            let fetch_refspec = "+refs/engrams/*:refs/engrams/*";
242	            let push_refspec = "refs/engrams/*:refs/engrams/*";
243	
244	            // Check if already configured by iterating existing values
245	            let fetch_exists = config
246	                .entries(Some(&fetch_key))
247	                .ok()
248	                .map(|mut entries| {
249	                    let mut found = false;
250	                    while let Some(Ok(entry)) = entries.next() {
251	                        if entry.value() == Some(fetch_refspec) {
252	                            found = true;
253	                            break;
254	                        }
255	                    }
256	                    found
257	                })
258	                .unwrap_or(false);
259	
260	            if !fetch_exists {
261	                config
262	                    .set_multivar(&fetch_key, "^$", fetch_refspec)
263	                    .or_else(|_| {
264	                        // If set_multivar fails (no existing entry), try adding
265	                        self.repo
266	                            .remote_add_fetch(remote_name, fetch_refspec)
267	                            .map(|_| ())
268	                    })
269	                    .map_err(CoreError::Git)?;
270	            }
271	
272	            let push_exists = config
273	                .entries(Some(&push_key))
274	                .ok()
275	                .map(|mut entries| {
276	                    let mut found = false;
277	                    while let Some(Ok(entry)) = entries.next() {
278	                        if entry.value() == Some(push_refspec) {
279	                            found = true;
280	                            break;
281	                        }
282	                    }
283	                    found
284	                })
285	                .unwrap_or(false);
286	
287	            if !push_exists {
288	                config
289	                    .set_multivar(&push_key, "^$", push_refspec)
290	                    .or_else(|_| {
291	                        self.repo
292	                            .remote_add_push(remote_name, push_refspec)
293	                            .map(|_| ())
294	                    })
295	                    .map_err(CoreError::Git)?;
296	            }
297	        }
298	
299	        Ok(())
300	    }
301	}
