10	
11	const SESSION_FILE: &str = "engram-session";
12	
13	/// Tracks an active recording session. Stored as JSON at `.git/engram-session`.
14	#[derive(Debug, Clone, Serialize, Deserialize)]
15	pub struct ActiveSession {
16	    pub engram_id: EngramId,
17	    pub agent: AgentInfo,
18	    pub started_at: DateTime<Utc>,
19	    pub commits: Vec<String>,
20	    pub token_usage: TokenUsage,
21	    /// True when this session was created by auto-capture (not `engram record`).
22	    /// Auto-captured sessions are cleaned up after post-commit.
23	    #[serde(default)]
24	    pub auto_capture: bool,
25	}
26	
27	impl ActiveSession {
28	    /// Create a new active session.
29	    pub fn new(engram_id: EngramId, agent: AgentInfo) -> Self {
30	        Self {
31	            engram_id,
32	            agent,
33	            started_at: Utc::now(),
34	            commits: Vec::new(),
35	            token_usage: TokenUsage::default(),
36	            auto_capture: false,
37	        }
38	    }
39	
40	    /// Path to the session file inside the .git directory.
41	    fn session_path(git_dir: &Path) -> PathBuf {
42	        git_dir.join(SESSION_FILE)
43	    }
44	
45	    /// Save the session to disk with an exclusive file lock.
46	    pub fn save(&self, git_dir: &Path) -> Result<(), CoreError> {
47	        let path = Self::session_path(git_dir);
48	        let json = serde_json::to_string_pretty(self)
49	            .map_err(|e| CoreError::Config(format!("Failed to serialize session: {e}")))?;
50	        let file = fs::OpenOptions::new()
51	            .write(true)
52	            .create(true)
53	            .truncate(true)
54	            .open(&path)?;
55	        fs2::FileExt::lock_exclusive(&file).map_err(CoreError::Io)?;
56	        (&file).write_all(json.as_bytes())?;
57	        fs2::FileExt::unlock(&file).map_err(CoreError::Io)?;
58	        Ok(())
59	    }
60	
61	    /// Load an active session if one exists, using a shared file lock.
62	    pub fn load(git_dir: &Path) -> Option<Self> {
63	        let path = Self::session_path(git_dir);
64	        let file = fs::OpenOptions::new().read(true).open(&path).ok()?;
65	        fs2::FileExt::lock_shared(&file).ok()?;
66	        let mut data = String::new();
67	        (&file).read_to_string(&mut data).ok()?;
68	        fs2::FileExt::unlock(&file).ok();
69	        serde_json::from_str(&data).ok()
70	    }
71	
72	    /// Remove the session file.
73	    pub fn cleanup(git_dir: &Path) {
74	        let path = Self::session_path(git_dir);
75	        let _ = fs::remove_file(path);
76	    }
77	
78	    /// Add a commit SHA to the session atomically with an exclusive lock.
79	    pub fn add_commit(&mut self, sha: &str, git_dir: &Path) -> Result<(), CoreError> {
80	        let path = Self::session_path(git_dir);
81	        let file = fs::OpenOptions::new().read(true).write(true).open(&path)?;
82	        fs2::FileExt::lock_exclusive(&file).map_err(CoreError::Io)?;
83	
84	        // Re-read under lock to get latest state
85	        let mut data = String::new();
86	        (&file).read_to_string(&mut data)?;
87	        let mut current: ActiveSession = serde_json::from_str(&data)
88	            .map_err(|e| CoreError::Config(format!("Session parse: {e}")))?;
89	        current.commits.push(sha.to_string());
90	
91	        // Write back
92	        let json = serde_json::to_string_pretty(&current)
93	            .map_err(|e| CoreError::Config(format!("Session serialize: {e}")))?;
94	        file.set_len(0)?;
95	        (&file).seek(SeekFrom::Start(0))?;
96	        (&file).write_all(json.as_bytes())?;
97	
98	        // Update self
99	        self.commits = current.commits;
100	        fs2::FileExt::unlock(&file).map_err(CoreError::Io)?;
101	        Ok(())
102	    }
103	}
