8	/// Rebuild the index from scratch by reading all engrams from Git.
9	pub fn rebuild_index(storage: &GitStorage, index_path: &Path) -> Result<usize, QueryError> {
10	    // Remove existing index
11	    if index_path.exists() {
12	        std::fs::remove_dir_all(index_path).map_err(QueryError::Io)?;
13	    }
14	
15	    let mut writer = EngramIndexWriter::open(index_path)?;
16	    let manifests = storage.list(&Default::default())?;
17	
18	    let mut count = 0;
19	    for manifest in &manifests {
20	        match storage.read(manifest.id.as_str()) {
21	            Ok(data) => {
22	                writer.index_engram(&data)?;
23	                count += 1;
24	            }
25	            Err(e) => {
26	                tracing::warn!("Failed to read engram {}: {e}", manifest.id);
27	            }
28	        }
29	    }
30	
31	    writer.commit()?;
32	
33	    tracing::info!("Indexed {count} engrams");
34	    Ok(count)
35	}
