9	/// High-level search engine that manages index lifecycle.
10	pub struct SearchEngine {
11	    index_path: PathBuf,
12	}
13	
14	impl SearchEngine {
15	    /// Open a search engine for a repository. Index is stored at `.git/engram-index/`.
16	    pub fn open(storage: &GitStorage) -> Result<Self, QueryError> {
17	        let git_dir = storage.repo().path();
18	        let index_path = git_dir.join("engram-index");
19	        Ok(Self { index_path })
20	    }
21	
22	    /// Ensure the index exists, creating it if needed.
23	    pub fn ensure_index(&self, storage: &GitStorage) -> Result<(), QueryError> {
24	        if !self.index_path.exists() || !self.index_path.join("meta.json").exists() {
25	            rebuild_index(storage, &self.index_path)?;
26	        }
27	        Ok(())
28	    }
29	
30	    /// Search engrams by free-text query.
31	    pub fn search(
32	        &self,
33	        storage: &GitStorage,
34	        query: &str,
35	        limit: usize,
36	    ) -> Result<Vec<SearchResult>, QueryError> {
37	        self.ensure_index(storage)?;
38	        let searcher = EngramSearcher::open(&self.index_path)?;
39	        searcher.search(query, limit)
40	    }
41	
42	    /// Search for engrams that touched a file.
43	    pub fn search_by_file(
44	        &self,
45	        storage: &GitStorage,
46	        file_path: &str,
47	        limit: usize,
48	    ) -> Result<Vec<SearchResult>, QueryError> {
49	        self.ensure_index(storage)?;
50	        let searcher = EngramSearcher::open(&self.index_path)?;
51	        searcher.search_by_file(file_path, limit)
52	    }
53	
54	    /// Index a single new engram (incremental update).
55	    ///
56	    /// If the index directory doesn't exist yet, this is a no-op (the index
57	    /// will be created on the first search via `ensure_index`).
58	    pub fn index_engram(&self, data: &EngramData) -> Result<(), QueryError> {
59	        if !self.index_path.exists() {
60	            tracing::debug!(
61	                "Search index not yet created at {}, skipping incremental update",
62	                self.index_path.display()
63	            );
64	            return Ok(());
65	        }
66	        let mut writer = EngramIndexWriter::open(&self.index_path)?;
67	        writer.index_engram(data)?;
68	        writer.commit()?;
69	        Ok(())
70	    }
71	
72	    /// Rebuild the index from scratch.
73	    pub fn rebuild(&self, storage: &GitStorage) -> Result<usize, QueryError> {
74	        rebuild_index(storage, &self.index_path)
75	    }
76	
77	    /// Return the index path.
78	    pub fn index_path(&self) -> &PathBuf {
79	        &self.index_path
80	    }
81	}
